class TransitionSettingsField(FieldBase):
    """
    Data from the `TrSS` field. This stores the config of the "Next transition" and "Transition style" blocks on the control
    panels.

    The mixer will send a field for every M/E unit in the mixer.

    There are two sets of style/layer settings. The first set is the active transition settings. The second one will store
    the transitions settings if you change any of them while a transition is active. These settings will be applied as soon
    as the transition ends. This is signified by blinking transition settings buttons in the official control panels.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      1    u8     M/E Index
    1      1    u8     Transition style
    2      1    u8     Next transition layers
    3      1    u8     Next transition style
    4      1    u8     Next transition next transition layers
    ====== ==== ====== ===========

    The `Transition style` is an enum of these values:

    === ================
    Key Transition style
    === ================
    0   Mix
    1   Dip
    2   Wipe
    3   DVE
    4   Sting
    === ================

    After parsing:

    :ivar index: M/E Index
    :ivar style: Transition style
    :ivar nt: Next transition layers
    :ivar style_next: Next transition style
    :ivar ntn: Next transition next transition layers
    """

    CODE = "TrSS"
    STRUCT = struct.Struct('>BBBB B')

    STYLE_MIX = 0
    STYLE_DIP = 1
    STYLE_WIPE = 2
    STYLE_DVE = 3
    STYLE_STING = 4

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.index = field[0]
        self.style = field[1]
        self.next_transition_bkgd = field[2] & (1 << 0) != 0
        self.next_transition_key1 = field[2] & (1 << 1) != 0
        self.next_transition_key2 = field[2] & (1 << 2) != 0
        self.next_transition_key3 = field[2] & (1 << 3) != 0
        self.next_transition_key4 = field[2] & (1 << 4) != 0
        self.style_next = field[3]
        self.next_transition_bkgd_next = field[4] & (1 << 0) != 0
        self.next_transition_key1_next = field[4] & (1 << 1) != 0
        self.next_transition_key2_next = field[4] & (1 << 2) != 0
        self.next_transition_key3_next = field[4] & (1 << 3) != 0
        self.next_transition_key4_next = field[4] & (1 << 4) != 0

    @classmethod
    def create(cls, style: int, nt: int, style_next: int, ntn: int, index: int = 0) -> Self:
        """
        :param index: M/E Index, defaults to 0
        :param style: Transition style
        :param nt: Next transition layers
        :param style_next: Next transition style
        :param ntn: Next transition next transition layers
        :return: Instance of TransitionSettingsField with the data applied
        """
        raw = cls.STRUCT.pack(style, nt, style_next, ntn, index)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into TransitionSettingsField.create()"""
        return self.style, self.nt, self.style_next, self.ntn, self.index

    def __repr__(self):
        return f"<transition-settings index={self.index} style={self.style}>"


