class TimeField(FieldBase):
    """
    Data from the `Time` field. This contains the value of the internal clock of the hardware.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      1    u8     Hours
    1      1    u8     Minutes
    2      1    u8     Seconds
    3      1    u8     Frames
    4      1    bool   Current mode uses dropframes
    5      3    ?      padding
    ====== ==== ====== ===========

    After parsing:

    :ivar hours: Hours
    :ivar minutes: Minutes
    :ivar seconds: Seconds
    :ivar frames: Frames
    :ivar is_dropframe: Current mode uses dropframes
    """

    CODE = "Time"
    STRUCT = struct.Struct('>BBBB ?3x')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.hours = field[0]
        self.minutes = field[1]
        self.seconds = field[2]
        self.frames = field[3]
        self.is_dropframe = field[4]


    @classmethod
    def create(cls, hours: int = 0, minutes: int = 0, seconds: int = 0, frames: int = 0, is_dropframe: bool = False) -> Self:
        """
        :param hours: Hours, defaults to 0
        :param minutes: Minutes, defaults to 0
        :param seconds: Seconds, defaults to 0
        :param frames: Frames, defaults to 0
        :param is_dropframe: Current mode uses dropframes, defaults to False
        :return: Instance of TimeField with the data applied
        """
        raw = cls.STRUCT.pack(hours, minutes, seconds, frames, is_dropframe)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into TimeField.create()"""
        return self.hours, self.minutes, self.seconds, self.frames, self.is_dropframe

    def total_seconds(self):
        """get the time as amount of seconds (excluding the frames)"""
        return self.seconds + (60 * self.minutes) + (60 * 60 * self.hours)

    def __repr__(self):
        return f"<time {self.hours} {self.minutes} {self.seconds} {self.frames}>"


class MixerEffectConfigField(FieldBase):
    """
    Data from the `_MeC` field. This stores basic info about the M/E units.

    The mixer will send multiple fields, one for each M/E unit.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      1    u8     M/E index
    1      1    u8     Number of keyers on this M/E
    2      2    ?      padding
    ====== ==== ====== ===========

    After parsing:

    :ivar index: M/E index
    :ivar keyers: Number of keyers on this M/E
    """

    CODE = "_MeC"
    STRUCT = struct.Struct('>BB2x')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.index = field[0]
        self.keyers = field[1]

    @classmethod
    def create(cls, index: int, keyers: int) -> Self:
        """
        :param index: M/E index
        :param keyers: Number of keyers on this M/E
        :return: Instance of MixerEffectConfigField with the data applied
        """
        raw = cls.STRUCT.pack(index, keyers)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into MixerEffectConfigField.create()"""
        return self.index, self.keyers

    def __repr__(self):
        return f"<mixer-effect-config index={self.index} keyers={self.keyers}>"


class VideoModeCapabilityField(FieldBase):
    """
    Data from the `_VMC` field. This describes all the video modes supported by the hardware and the associated multiview
    and downconvert modes.

    The first 2 bytes is the number of modes supported, then there's a 13 byte block that's repeated for every mode that has
    the mode number, the possible multiview modes in this mode and the possible downconvert modes.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      2    u16    Number of video modes
    ====== ==== ====== ===========

    Followed by this repeated block:

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      1    u8     Video mode number referring to a VideoMode
    1      3    ?      padding
    4      4    u32    Multiview modes bitfield
    8      4    u32    Downscale modes bitfield
    12     1    bool   Requires reconfiguration
    ====== ==== ====== ===========

    After parsing:

    :ivar count: Number of video modes
    """

    CODE = "_VMC"
    STRUCT = struct.Struct('>H')
    REPEATED = struct.Struct('>B3x I I ?')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack_from(raw, 0)
        self.count = field[0]
        self.modes = []
        for i in range(self.count):
            rf = self.REPEATED.unpack_from(raw, self.STRUCT.size + (i * self.REPEATED.size))
            self.modes.append({
                "modenum": rf[0],
                "multiview": self._bitfield_to_modes(rf[1]),
                "downscale": self._bitfield_to_modes(rf[2]),
                "reconfig": rf[3],
                "mode": self._int_to_mode(rf[0]),
            })


    @classmethod
    def create(cls, count: int) -> Self:
        """
        :param count: Number of video modes
        :return: Instance of VideoModeCapabilityField with the data applied
        """
        raw = cls.STRUCT.pack(count)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into VideoModeCapabilityField.create()"""
        return self.count,

    def _int_to_mode(self, mode: int):
        """The VideoMode corresponding with this mode"""
        return VideoModeField(VideoModeField.STRUCT.pack(mode))

    def _bitfield_to_modes(self, bitfield: int):
        """Convert a mode bitfield to a list of VideoModeField instances"""
        result = []
        for i in range(0, 32):
            if bitfield & (2 ** i):
                result.append(self._int_to_mode(i))
        return result

    def __repr__(self):
        return f"<video-mode-capability count={self.count}>"


class FirmwareVersionField(FieldBase):
    """
    Data from the `_ver` field. This stores the major/minor firmware version numbers

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      2    u16    Major version
    2      2    u16    Minor version
    ====== ==== ====== ===========

    After parsing:

    :ivar major: Major version
    :ivar minor: Minor version
    :ivar version: Human readable version string
    """

    CODE = "_ver"
    STRUCT = struct.Struct('>HH')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.major = field[0]
        self.minor = field[1]

        self.version = f"{self.major}.{self.minor}"

    @classmethod
    def create(cls, major: int, minor: int) -> Self:
        """
        :param major: Major version
        :param minor: Minor version
        :return: Instance of FirmwareVersionField with the data applied
        """
        raw = cls.STRUCT.pack(major, minor)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into FirmwareVersionField.create()"""
        return self.major, self.minor

    def __repr__(self):
        return f"<firmware-version {self.version}>"


class ProductNameField(FieldBase):
    """
    Data from the `_pin` field. This stores the product name and model for this switcher

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      40   string Product name
    40     4    u32    Model code
    ====== ==== ====== ===========

    After parsing:

    :ivar name: Product name
    :ivar model: Model code
    """

    CODE = "_pin"
    STRUCT = struct.Struct('>40s I')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.name = self._get_string(field[0])
        self.model = field[1]

    @classmethod
    def create(cls, name: str, model: int = 0) -> Self:
        """
        :param name: Product name
        :param model: Model code, defaults to 0
        :return: Instance of ProductNameField with the data applied
        """
        raw = cls.STRUCT.pack(name, model)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into ProductNameField.create()"""
        return self.name, self.model

    def __repr__(self):
        return f"<product-name {self.name} model={self.model}>"


class InputPropertiesField(FieldBase):
    """
    Data from the `InPr` field. This stores information about all the internal and external inputs.

    The mixer will send multiple fields, one for each input

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      2    u16    Source index
    2      20   string Long name
    22     4    string Short name for button
    26     1    bool   Name is unchanged from factory naming
    27     1    ?      Unknown
    28     2    u16    WHEE
    30     2    u16    WHEEE
    32     2    u16    WHEOOO
    34     1    u8     describes routing options for this port
    35     1    u8     describes routing options for this port
    ====== ==== ====== ===========

    After parsing:

    :ivar index: Source index
    :ivar name: Long name
    :ivar short_name: Short name for button
    :ivar default_name: Name is unchanged from factory naming
    :ivar source_ports: WHEE
    :ivar external_port_type: WHEEE
    :ivar port_type: WHEOOO
    :ivar bitfield_availability: describes routing options for this port
    :ivar bitfield_availability2: describes routing options for this port
    """

    CODE = "InPr"
    STRUCT = struct.Struct('>H20s4s?x HH HBB')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.index = field[0]
        self.name = self._get_string(field[1])
        self.short_name = self._get_string(field[2])
        self.default_name = field[3]
        self.source_ports = field[4]
        self.external_port_type = field[5]
        self.port_type = field[6]
        self.available_aux = field[7] & (1 << 0) != 0
        self.available_multiview = field[7] & (1 << 1) != 0
        self.available_supersource_art = field[7] & (1 << 2) != 0
        self.available_supersource_box = field[7] & (1 << 3) != 0
        self.available_key_source = field[7] & (1 << 4) != 0
        self.available_aux1 = field[7] & (1 << 5) != 0
        self.available_aux2 = field[7] & (1 << 6) != 0
        self.available_usb = field[7] & (1 << 7) != 0
        self.available_me1 = field[8] & (1 << 0) != 0
        self.available_m2 = field[8] & (1 << 1) != 0

    @classmethod
    def create(cls, index: int, name: str, short_name: str, default_name: bool, source_ports: int, external_port_type: int, port_type: int, bitfield_availability: int, bitfield_availability2: int) -> Self:
        """
        :param index: Source index
        :param name: Long name
        :param short_name: Short name for button
        :param default_name: Name is unchanged from factory naming
        :param source_ports: WHEE
        :param external_port_type: WHEEE
        :param port_type: WHEOOO
        :param bitfield_availability: describes routing options for this port
        :param bitfield_availability2: describes routing options for this port
        :return: Instance of InputPropertiesField with the data applied
        """
        raw = cls.STRUCT.pack(index, name, short_name, default_name, source_ports, external_port_type, port_type,
            bitfield_availability, bitfield_availability2)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into InputPropertiesField.create()"""
        return self.index, self.name, self.short_name, self.default_name, self.source_ports, self.external_port_type, self.port_type, self.bitfield_availability, self.bitfield_availability2

    def __repr__(self):
        return f"<input-properties index={self.index} name={self.name} short_name={self.short_name}>"


class VideoModeField(FieldBase):
    """
    Data from the `VidM` field. This sets the video standard the switcher operates on internally.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      1    u8     Video mode
    1      3    ?      Padding
    ====== ==== ====== ===========

    The `Video mode` is an enum of these values:

    === ==========
    Key Video mode
    === ==========
    0   NTSC (525i59.94)
    1   PAL (625i50)
    2   NTSC widescreen (525i59.94)
    3   PAL widescreen (625i50)
    4   720p50
    5   720p59.94
    6   1080i50
    7   1080i59.94
    8   1080p23.98
    9   1080p24
    10  1080p25
    11  1080p29.97
    12  1080p50
    13  1080p59.94
    14  4k23.98
    15  4k24
    16  4k25
    17  4k29.97
    18  4k50
    19  4k59.94
    20  8k23.98
    21  8k24
    22  8k25
    23  8k29.97
    24  8k50
    25  8k59.94
    26  1080p30
    27  1080p60
    28  720p60
    29  1080i60
    === ==========

    After parsing:

    :ivar mode: Video mode
    :ivar resolution: vertical resolution of the mode
    :ivar interlaced: the current mode is interlaced
    :ivar rate: the refresh rate of the mode
    :ivar widescreen: this is not a 4:3 resolution
    """

    CODE = "VidM"
    STRUCT = struct.Struct('>B3x')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.mode = field[0]

        lut_mode = {
                0: (True, 59.94, 525, False),
                1: (True, 50, 625, False),
                2: (True, 59.94, 525, True),
                3: (True, 50, 625, True),
                4: (False, 50, 720, True),
                5: (False, 59.94, 720, True),
                6: (True, 50, 1080, True),
                7: (True, 59.94, 1080, True),
                8: (False, 23.98, 1080, True),
                9: (False, 24, 1080, True),
                10: (False, 25, 1080, True),
                11: (False, 29.97, 1080, True),
                12: (False, 50, 1080, True),
                13: (False, 59.94, 1080, True),
                14: (False, 23.98, 2160, True),
                15: (False, 24, 2160, True),
                16: (False, 25, 2160, True),
                17: (False, 29.97, 2160, True),
                18: (False, 50, 2160, True),
                19: (False, 59.94, 2160, True),
                20: (False, 23.98, 4320, True),
                21: (False, 24, 4320, True),
                22: (False, 25, 4320, True),
                23: (False, 29.97, 4320, True),
                24: (False, 50, 4320, True),
                25: (False, 59.94, 4320, True),
                26: (False, 30, 1080, True),
                27: (False, 60, 1080, True),
                28: (False, 60, 720, True),
                29: (True, 60, 1080, True)
        }
        self.resolution = lut_mode[self.mode][2]
        self.interlaced = lut_mode[self.mode][0]
        self.rate = lut_mode[self.mode][1]
        self.widescreen = lut_mode[self.mode][3]

    @classmethod
    def create(cls, mode: int) -> Self:
        """
        :param mode: Video mode
        :return: Instance of VideoModeField with the data applied
        """
        raw = cls.STRUCT.pack(mode)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into VideoModeField.create()"""
        return self.mode,

    def get_resolution(self):
        """get the resolution as a (width, height) tuple"""
        lut = {
         525: [720, 480], 625: [720, 576], 720: [1280, 720], 1080: [1920, 1080], 2160: [3840, 2160], 4320: [7680, 4320]
        }
        return lut[self.resolution]

    def get_pixels(self):
        """get the total number of pixels in a single frame"""
        width, height = self.get_resolution()
        return width * height

    def get_label(self):
        """get a text description of the current mode"""
        if self.resolution is None:
            return f'unknown [{self.mode}]'

        pi = 'p'
        if self.interlaced:
            pi = 'i'
        aspect = ''
        if self.resolution < 720:
            if self.widescreen:
                aspect = ' 16:9'
            else:
                aspect = ' 4:3'
        return f'{self.resolution}{pi}{self.rate}{aspect}'

    def __repr__(self):
        return f"<video-mode {self.get_label()}>"


class MediaplayerSelectedField(FieldBase):
    """
    Data from the `MPCE` field. This defines what media from the media pool is loaded in a specific media player. There is
    one MPCE field per mediaplayer in the hardware.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      1    u8     Mediaplayer index
    1      1    u8     Source type
    2      1    u8     Source index loaded in the mediaplayer
    3      1    ?      padding
    ====== ==== ====== ===========

    After parsing:

    :ivar index: Mediaplayer index
    :ivar source_type: Source type
    :ivar slot: Source index loaded in the mediaplayer
    """

    CODE = "MPCE"
    STRUCT = struct.Struct('>BBBx')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.index = field[0]
        self.source_type = field[1]
        self.slot = field[2]

    @classmethod
    def create(cls, index: int, source_type: int, slot: int) -> Self:
        """
        :param index: Mediaplayer index
        :param source_type: Source type
        :param slot: Source index loaded in the mediaplayer
        :return: Instance of MediaplayerSelectedField with the data applied
        """
        raw = cls.STRUCT.pack(index, source_type, slot)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into MediaplayerSelectedField.create()"""
        return self.index, self.source_type, self.slot

    def __repr__(self):
        return f"<mediaplayer-selected index={self.index} source_type={self.source_type} slot={self.slot}>"


class FileTransferContinueDataField(FieldBase):
    """
    Data from the `FTCD`. This is a field telling the client what chunk size to use to continue the upload of data to the
    hardware.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      2    u16    Store id
    2      4    ?      padding
    6      2    u16    Chunk size
    8      2    u16    Chunk count
    10     2    ?      padding
    ====== ==== ====== ===========

    After parsing:

    :ivar store: Store id
    :ivar size: Chunk size
    :ivar count: Chunk count
    """

    CODE = "FTCD"
    STRUCT = struct.Struct('>H4xH H2x')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.store = field[0]
        self.size = field[1]
        self.count = field[2]

    @classmethod
    def create(cls, store: int, size: int, count: int) -> Self:
        """
        :param store: Store id
        :param size: Chunk size
        :param count: Chunk count
        :return: Instance of FileTransferContinueDataField with the data applied
        """
        raw = cls.STRUCT.pack(store, size, count)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into FileTransferContinueDataField.create()"""
        return self.store, self.size, self.count

    def __repr__(self):
        return f"<file-transfer-continue-data store={self.store} size={self.size} count={self.count}>"


class FileTransferDataField(FieldBase):
    """
    Data from the `FTDa`. This is an incoming chunk of data for a running file transfer.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      2    u16    Transfer id
    2      2    u16    Data length
    ====== ==== ====== ===========

    After parsing:

    :ivar transfer: Transfer id
    :ivar size: Data length
    """

    CODE = "FTDa"
    STRUCT = struct.Struct('>HH')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.transfer = field[0]
        self.size = field[1]
        self.data = raw[self.STRUCT.size:(self.STRUCT.size + self.size)]

    @classmethod
    def create(cls, transfer: int, size: int) -> Self:
        """
        :param transfer: Transfer id
        :param size: Data length
        :return: Instance of FileTransferDataField with the data applied
        """
        raw = cls.STRUCT.pack(transfer, size)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into FileTransferDataField.create()"""
        return self.transfer, self.size

    def __repr__(self):
        return f"<file-transfer-data transfer={self.transfer} size={self.size}>"


